options.styles:
@font-face { font-family: 'Plow Young Serif'; src: url('public/build/plow-brand/youngserif.woff2') format('woff2'); font-display: swap; }
& > .dt-row { margin: 0; padding: 0; border: 0; flex: 1; display: flex; }
.plow-heading { display: flex; align-items: center; flex: 1; gap: 20px; padding: 12px 28px; min-width: 0; color: #FFF4DF; background-color: #1A130D; border: 1px solid #6A934F; border-radius: 3px; }
.plow-wordmark { width: clamp(92px, 9vw, 128px); height: auto; flex: 0 0 auto; }
.plow-heading h1 { color: inherit; margin: 0; font: 400 clamp(24px, 2.5vw, 40px) / 1.15 'Plow Young Serif', Georgia, serif; }
